proc HD_Dist_Silently { args } {



    global exmh msg

    set exmh(ctype) {dist}

    if {[string length $args] == 0} {

	set args Mh_DistSetup

    }



    if [MsgOk $msg(id) m] {

	if {[string compare [info command $args] $args] == 0} {

	    # Old interface with hook procedure

	    if [catch {$args $exmh(folder) $m} err] {   ;# Setup draft msg

